#!/usr/bin/env node
'use strict';
/**
 * Package the engine for non-Node runtimes (browser <script>, JavaScriptCore in a macOS app, ...).
 *   node tools/bundle.js
 * Writes:
 *   engine/dist/                      THE HOST PACKAGE: farsi-ime-engine.js (global `FarsiIME`, incl. FarsiIME.host) + lexicon.tsv,
 *                                     bigrams.tsv, aliases.tsv + VERSION.json (sizes, sha256). A Mac app embeds exactly this folder.
 *   assets/vendor/farsi-ime-engine.js    the same file, for the website
 *   assets/data/*.js                     the SAME lexicon/bigrams/aliases strings wrapped as scripts for the website
 *   (legacy note) assets/data/lexicon.js window.FARSI_LEXICON = "<tsv>"  (so the site also works from file://)
 *   assets/data/aliases.js               window.FARSI_ALIASES = "<tsv>"
 *   assets/data/bigrams.js               window.FARSI_BIGRAMS = "<tsv>"   (previous-word context)
 */
const fs = require('fs');
const path = require('path');
const ROOT = path.join(__dirname, '..');
const SRC = path.join(ROOT, 'engine/src');

const files = fs.readdirSync(SRC).filter(f => f.endsWith('.js')).sort();
let out = '/* farsi-ime-engine — generated by tools/bundle.js from engine/src; do not edit. */\n(function (root) {\n"use strict";\nvar defs = {}, cache = {};\nfunction req(n) { n = n.replace(/^\\.\\//, "").replace(/\\.js$/, ""); if (cache[n]) return cache[n].exports; var m = cache[n] = { exports: {} }; if (!defs[n]) throw new Error("module not found: " + n); defs[n](m, m.exports, req); return m.exports; }\n';
for (const f of files) {
  const name = f.replace(/\.js$/, '');
  const code = fs.readFileSync(path.join(SRC, f), 'utf8').replace(/^'use strict';\n/, '');
  out += `defs[${JSON.stringify(name)}] = function (module, exports, require) {\n${code}\n};\n`;
}
out += 'root.FarsiIME = req("index");\n})(typeof self !== "undefined" ? self : this);\n';

fs.mkdirSync(path.join(ROOT, 'engine/dist'), { recursive: true });
fs.mkdirSync(path.join(ROOT, 'assets/vendor'), { recursive: true });
fs.mkdirSync(path.join(ROOT, 'assets/data'), { recursive: true });
fs.writeFileSync(path.join(ROOT, 'engine/dist/farsi-ime-engine.js'), out);
fs.writeFileSync(path.join(ROOT, 'assets/vendor/farsi-ime-engine.js'), out);

// compact lexicon: word \t logp \t zwnj-form \t hints   (drops only the trailing source column; logp keeps the build's precision)
const tsv = fs.readFileSync(path.join(ROOT, 'data/build/lexicon.tsv'), 'utf8').split('\n').filter(Boolean).map(l => {
  const p = l.split('\t');
  let row = p[0] + '\t' + p[1];
  if (p[2] || p[3]) row += '\t' + (p[2] || '') + (p[3] ? '\t' + p[3] : '');
  return row;
}).join('\n');
const bigrams = fs.existsSync(path.join(ROOT, 'data/build/bigrams.tsv')) ? fs.readFileSync(path.join(ROOT, 'data/build/bigrams.tsv'), 'utf8') : '';
const aliases = fs.readFileSync(path.join(ROOT, 'data/aliases.tsv'), 'utf8');

// 1) the host package: everything a native app needs, in neutral formats. engine/dist/ IS the deliverable for a Mac app.
const dist = path.join(ROOT, 'engine/dist');
fs.writeFileSync(path.join(dist, 'lexicon.tsv'), tsv);
fs.writeFileSync(path.join(dist, 'bigrams.tsv'), bigrams);
fs.writeFileSync(path.join(dist, 'aliases.tsv'), aliases);
const sha = f => require('crypto').createHash('sha256').update(fs.readFileSync(path.join(dist, f))).digest('hex');
const distFiles = ['farsi-ime-engine.js', 'lexicon.tsv', 'bigrams.tsv', 'aliases.tsv'];
fs.writeFileSync(path.join(dist, 'VERSION.json'), JSON.stringify({
  built: new Date().toISOString(), hostApi: 'FarsiIME.host (string in / string out; see engine/src/host.js)',
  lexiconWords: tsv.split('\n').length, bytes: Object.fromEntries(distFiles.map(f => [f, fs.statSync(path.join(dist, f)).size])),
  sha256: Object.fromEntries(distFiles.map(f => [f, sha(f)])),
}, null, 1) + '\n');

// 2) the website gets the very same strings, wrapped as scripts so it also works from file://
fs.writeFileSync(path.join(ROOT, 'assets/data/lexicon.js'), 'window.FARSI_LEXICON = ' + JSON.stringify(tsv) + ';\n');
if (bigrams) fs.writeFileSync(path.join(ROOT, 'assets/data/bigrams.js'), 'window.FARSI_BIGRAMS = ' + JSON.stringify(bigrams) + ';\n');
fs.writeFileSync(path.join(ROOT, 'assets/data/aliases.js'), 'window.FARSI_ALIASES = ' + JSON.stringify(aliases) + ';\n');
console.log('bundle:', (out.length / 1024).toFixed(0) + ' KB engine,', (tsv.length / 1048576).toFixed(1) + ' MB lexicon');
